#!/usr/bin/python
from __future__ import print_function

import os
import sqlite3
import sys

LOCK_WAIT_SECONDS = 5


def fail(message, status):
    sys.stderr.write('ERROR: %s\n' % message)
    return status


def main(argv):
    if len(argv) != 3:
        return fail('usage: reserve.py REQUEST_ID POSITIVE_QUANTITY', 2)

    request_id = argv[1]
    if not request_id:
        return fail('request ID must not be empty', 2)

    try:
        quantity = int(argv[2], 10)
    except ValueError:
        return fail('quantity must be a positive integer', 2)
    if quantity <= 0:
        return fail('quantity must be a positive integer', 2)

    base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    db_path = os.path.join(base, 'stock.db')
    db = None
    in_transaction = False

    try:
        db = sqlite3.connect(db_path, timeout=LOCK_WAIT_SECONDS,
                             isolation_level=None)
        db.execute('PRAGMA busy_timeout=%d' % (LOCK_WAIT_SECONDS * 1000))

        # Take the write reservation before reading either table.  This makes
        # the idempotency check and stock decrement one serialized operation.
        db.execute('BEGIN IMMEDIATE')
        in_transaction = True

        previous = db.execute(
            'SELECT quantity FROM reservations WHERE request_id=?',
            (request_id,)).fetchone()
        if previous is not None:
            db.execute('COMMIT')
            in_transaction = False
            print('RESERVED %s %d' % (request_id, previous[0]))
            return 0

        cursor = db.execute(
            'UPDATE stock SET remaining=remaining-? '
            'WHERE id=1 AND remaining>=?',
            (quantity, quantity))
        if cursor.rowcount != 1:
            db.execute('ROLLBACK')
            in_transaction = False
            return fail('insufficient stock', 3)

        db.execute(
            'INSERT INTO reservations (request_id, quantity) VALUES (?, ?)',
            (request_id, quantity))
        db.execute('COMMIT')
        in_transaction = False
        print('RESERVED %s %d' % (request_id, quantity))
        return 0
    except sqlite3.OperationalError as error:
        if in_transaction and db is not None:
            try:
                db.execute('ROLLBACK')
            except sqlite3.Error:
                pass
        if 'locked' in str(error).lower() or 'busy' in str(error).lower():
            return fail('database remained busy for %d seconds' %
                        LOCK_WAIT_SECONDS, 4)
        return fail('database error: %s' % error, 4)
    except sqlite3.Error as error:
        if in_transaction and db is not None:
            try:
                db.execute('ROLLBACK')
            except sqlite3.Error:
                pass
        return fail('database error: %s' % error, 4)
    finally:
        if db is not None:
            db.close()


if __name__ == '__main__':
    sys.exit(main(sys.argv))
